using Relic.Core.Effects;
using Relic.Core.Random;
using Relic.Items;

namespace Relic.Character
{
    /// <summary>
    /// Debug kits: a random weapon, armor, relic and two trinkets for a tier, generated by
    /// the real item pipeline in template mode (no LLM). Deterministic from (world seed, roll).
    /// </summary>
    public sealed class KitRoller
    {
        static readonly BaseType[] Weapons = { BaseType.Sword, BaseType.Greatsword, BaseType.Bow, BaseType.Staff, BaseType.Tome };
        static readonly BaseType[] Armors = { BaseType.LightArmor, BaseType.MediumArmor, BaseType.HeavyArmor };
        static readonly Rarity[] Rarities = { Rarity.Common, Rarity.Uncommon, Rarity.Rare, Rarity.Epic };

        readonly ulong _worldSeed;
        readonly ItemGenerator _generator;

        public KitRoller(ulong worldSeed)
        {
            _worldSeed = worldSeed;
            _generator = new ItemGenerator(StubWorld.Create(worldSeed));
        }

        /// <param name="roll">Roll counter (F7 presses); each roll uses its own item indices.</param>
        /// <param name="weapon">Force a weapon type (captures), or null for random.</param>
        /// <param name="armor">Force an armor type, or null for random.</param>
        public HeroKit Roll(int tier, int roll, BaseType? weapon = null, BaseType? armor = null)
        {
            var rng = new Pcg32(Hash.Combine(_worldSeed, Hash.Of("character.kit"), unchecked((ulong)roll)));
            int baseIndex = 1_000_000 + roll * 8;
            BaseType wt = weapon ?? Weapons[rng.Range(0, Weapons.Length)];
            BaseType at = armor ?? Armors[rng.Range(0, Armors.Length)];
            return new HeroKit
            {
                Weapon = Make(baseIndex + 0, tier, RollRarity(ref rng), wt),
                Armor = Make(baseIndex + 1, tier, RollRarity(ref rng), at),
                Relic = Make(baseIndex + 2, tier, Rarity.Legendary, BaseType.Relic),
                Trinket1 = Make(baseIndex + 3, tier, RollRarity(ref rng), BaseType.Trinket),
                Trinket2 = Make(baseIndex + 4, tier, RollRarity(ref rng), BaseType.Trinket),
            };
        }

        static Rarity RollRarity(ref Pcg32 rng) => Rarities[rng.Range(0, Rarities.Length)];

        Item Make(int index, int tier, Rarity rarity, BaseType type) =>
            _generator.Generate(new ItemSpec { WorldSeed = _worldSeed, Index = index, Tier = tier, Rarity = rarity, BaseType = type });
    }
}
